export const SHORE_CLUES=[
 {x:32,y:8,name:'波間の木箱',text:'木箱には灯台と同じ星形の金具が残っている。島の外からではなく、灯台から流れ着いたようだ。'},
 {x:43,y:8,name:'青い貝の歌',text:'青い貝を耳に当てると、波の奥から途切れた旋律が聞こえる。浜のモンスターたちが同じ方向を見ている。'},
 {x:40,y:15,name:'砕けた航路石',text:'航路石の裂け目に淡い雷が走る。灯台の光を浜へ運ぶ道が、何者かに乱されている。'}
];
export function migrateCampaign(s){if(s.campaign===undefined){const throughShore=s.ended||s.badges?.includes(1),throughForest=throughShore||s.badges?.includes(0);s.campaign={schema:2,chapter:throughShore?5:throughForest?3:1,step:0,baseWins:s.wins||0,baseCaptures:s.captures||0,claimed:throughShore?[1,2,3,4]:throughForest?[1,2]:[],discoveries:[]};return s;}const c=s.campaign,legacySchema=c.schema===undefined;if(c.discoveries===undefined)c.discoveries=[];if(c.schema===undefined)c.schema=2;if(legacySchema&&(s.ended||s.badges?.includes(1))&&c.chapter<5){c.chapter=5;c.step=0;c.claimed=[...new Set([...c.claimed,1,2,3,4])];c.baseWins=s.wins||0;c.baseCaptures=s.captures||0;}return s;}
function validCampaign(c){return c===undefined||!!c&&!Array.isArray(c)&&(c.schema===undefined||c.schema===2)&&Number.isInteger(c.chapter)&&c.chapter>=1&&c.chapter<=9&&Number.isInteger(c.step)&&c.step>=0&&c.step<=2&&Number.isInteger(c.baseWins)&&c.baseWins>=0&&Number.isInteger(c.baseCaptures)&&c.baseCaptures>=0&&Array.isArray(c.claimed)&&c.claimed.length<=8&&new Set(c.claimed).size===c.claimed.length&&c.claimed.every(v=>Number.isInteger(v)&&v>=1&&v<=8)&&(c.discoveries===undefined||Array.isArray(c.discoveries)&&c.discoveries.length<=SHORE_CLUES.length&&new Set(c.discoveries).size===c.discoveries.length&&c.discoveries.every(v=>Number.isInteger(v)&&v>=0&&v<SHORE_CLUES.length));}
export function campaignDiscover(s,id){migrateCampaign(s);const c=s.campaign;if(c.chapter!==3||c.step!==1||!Number.isInteger(id)||id<0||id>=SHORE_CLUES.length||c.discoveries.includes(id))return false;c.discoveries.push(id);return true;}
export function campaignObjective(s){migrateCampaign(s);const c=s.campaign;if(c.chapter===1){if(c.step===0)return '第1章：里の長老から森の異変を聞こう。';return s.captures>c.baseCaptures?'第1章：新しい仲間を連れて長老へ報告しよう。':'第1章：里の近くの草むらで野生の仲間を1体捕獲しよう。';}if(c.chapter===2){if(c.step===0)return s.wins>=c.baseWins+3?'第2章：3勝した成果を長老へ報告しよう。':`第2章：森であと${Math.max(0,c.baseWins+3-s.wins)}勝し、仲間をLv.5前後まで育てよう。`;return s.badges.includes(0)?'第2章：若葉の紋章を長老へ見せよう。':'第2章：北西の森で番人ミナに挑もう。目安はLv.5〜6の3体。';}if(c.chapter===3){if(c.step===0)return '第3章：里の長老から潮風の浜の異変を聞こう。';const left=SHORE_CLUES.length-c.discoveries.length;return left?`第3章：潮風の浜で光る漂着物をあと${left}か所調べよう。`:'第3章：浜で見つけた三つの手がかりを長老へ報告しよう。';}if(c.chapter===4){if(c.step===0){const left=Math.max(0,c.baseWins+4-s.wins);return left?`第4章：潮風の浜であと${left}勝し、仲間をLv.9〜11まで育てよう。`:'第4章：浜での鍛錬を終えたことを長老へ報告しよう。';}return s.badges.includes(1)?'第4章：潮の紋章を長老へ見せよう。':'第4章：北東の浜で番人ナギに挑もう。目安はLv.9〜11の3〜4体。';}return null;}
export function advanceCampaign(s){migrateCampaign(s);const c=s.campaign;if(c.chapter===1){if(c.step===0){c.step=1;c.baseCaptures=s.captures;return {changed:true,title:'第1章　消えた森の足音',text:'森から小さな足音が消え、灯台の光も弱まっている。まずは草むらで野生の仲間を一体迎え、森の様子を確かめておくれ。',objective:campaignObjective(s)};}if(s.captures>c.baseCaptures){c.claimed.push(1);c.chapter=2;c.step=0;c.baseWins=s.wins;s.balls+=3;s.potions+=1;return {changed:true,title:'第1章　完了',text:'新しい仲間の気配が、森へ道をつないだ。次は力を合わせる練習をして、若葉の番人ミナへ備えよう。',reward:'捕獲クリスタル3個・回復薬1個',objective:campaignObjective(s)};}return {changed:false,title:'第1章　消えた森の足音',text:'里の近くなら野生の仲間もLv.1。HPを減らしてから捕獲クリスタルを使うと迎えやすい。',objective:campaignObjective(s)};}if(c.chapter===2){if(c.step===0&&s.wins>=c.baseWins+3){c.step=1;return {changed:true,title:'第2章　若葉の紋章',text:'仲間たちの歩調がそろった。北西の森で番人ミナが待っている。炎属性と「守る」を使い、二体の連携を越えておいで。',objective:campaignObjective(s)};}if(c.step===1&&s.badges.includes(0)){c.claimed.push(2);c.chapter=3;c.step=0;c.baseWins=s.wins;c.baseCaptures=s.captures;s.coins+=300;s.balls+=3;return {changed:true,title:'第2章　完了',text:'若葉の紋章が森の道を照らした。潮風の浜へ続く門が開き、灯台の謎は次の光へつながっている。',reward:'300コイン・捕獲クリスタル3個',objective:campaignObjective(s)};}return {changed:false,title:'第2章　若葉の紋章',text:c.step===0?'森の草むらで戦い、三勝して仲間の役割を確かめよう。無理な時は診療所で無料回復できる。':'ミナは二体で戦う。炎属性の仲間、回復薬、気力を使う技を整えよう。',objective:campaignObjective(s)};}if(c.chapter===3){if(c.step===0){c.step=1;c.discoveries=[];return {changed:true,title:'第3章　潮騒に眠る歌',text:'浜から、灯台の光に似た品が三つ流れ着いたそうだ。北東の潮風の浜へ向かい、光っている漂着物をすべて調べておくれ。',objective:campaignObjective(s)};}if(c.discoveries.length===SHORE_CLUES.length){c.claimed.push(3);c.chapter=4;c.step=0;c.baseWins=s.wins;s.coins+=250;s.potions+=2;return {changed:true,title:'第3章　完了',text:'三つの手がかりは、灯台の光を運ぶ「潮の航路」が乱れている証だった。ナギなら海の声から原因をたどれるはずだ。',reward:'250コイン・回復薬2個',objective:campaignObjective(s)};}return {changed:false,title:'第3章　潮騒に眠る歌',text:`浜の光る印はあと${SHORE_CLUES.length-c.discoveries.length}か所。島の地図で潮風の浜へ移動し、木箱・青い貝・砕けた石を探そう。`,objective:campaignObjective(s)};}if(c.chapter===4){if(c.step===0&&s.wins>=c.baseWins+4){c.step=1;return {changed:true,title:'第4章　雷雲の航路',text:'浜のモンスターと歩調を合わせる力がついた。北東の番人ナギに挑み、水の守りを越えて潮の航路を取り戻そう。',objective:campaignObjective(s)};}if(c.step===1&&s.badges.includes(1)){c.claimed.push(4);c.chapter=5;c.step=0;c.baseWins=s.wins;c.baseCaptures=s.captures;s.coins+=400;s.balls+=5;s.potions+=2;return {changed:true,title:'第4章　完了',text:'潮の紋章が青く輝き、浜から高原へ一本の光が走った。乱れの源は、火口の奥へ続いている。',reward:'400コイン・捕獲クリスタル5個・回復薬2個',objective:null};}return {changed:false,title:'第4章　雷雲の航路',text:c.step===0?'浜の草むらで四勝しよう。草・雷属性と回復役を組み合わせると、ナギ戦の練習になる。':'ナギは水属性の二体で戦う。草か雷属性の技、守る、交代を使って潮の守りを崩そう。',objective:campaignObjective(s)};}return null;}
export function migratePostgame(s){if(s.postgame===undefined)s.postgame={medals:0,bestFloor:0,runs:0,tower:null};const defaults={riftBest:0,riftRuns:0,rift:null,guardianRanks:[0,0,0,0],guardianWins:0};for(const [key,value] of Object.entries(defaults))if(s.postgame[key]===undefined)s.postgame[key]=Array.isArray(value)?[...value]:value;return s;}
export function heal(s){[...s.party,...s.box].forEach(m=>{m.hp=maxHP(m);m.energy=4;});}
export function xpToNext(level){return 24+16*level;}
export function migrateGrowth(s){if(s.growthVersion!==2){for(const m of [...s.party,...s.box])m.xp=Math.floor(Math.min(.999,m.xp/(m.level*12))*xpToNext(m.level));s.growthVersion=2;}return s;}
export function addXP(m,amount){const events=[];m.xp+=Math.min(xpToNext(m.level),Math.max(0,amount));while(m.level<40&&m.xp>=xpToNext(m.level)){m.xp-=xpToNext(m.level);m.level++;for(const v of learnedMoves(m).filter(v=>v.level===m.level)){events.push(`${SPECIES[m.id].name}は「${v.name}」を覚えた！`);if(Array.isArray(m.moves)&&m.moves.length<4&&!m.moves.includes(v.id))m.moves.push(v.id);}m.hp=Math.min(maxHP(m),m.hp+8);events.push(`${SPECIES[m.id].name}はLv.${m.level}になった！`);if(m.level>=10&&SPECIES[m.id].evolve!==undefined){m.id=SPECIES[m.id].evolve;m.hp=maxHP(m);events.push(`${SPECIES[m.id].name}へ進化した！`);}}if(m.level===40)m.xp=0;return events;}
export function active(s){return s.party.findIndex(m=>m.hp>0);}
export function encounter(s,region,boss=false,final=false){const r=REGIONS[region];const opening=!boss&&!final&&region===0&&s.wins===0&&s.badges.length===0;const id=opening?([0,1,2].includes(s.party[0].id)?s.party[0].id:0):final?14:boss?r.boss:r.pool[Math.floor(rng(s)*r.pool.length)];const level=opening?1:final?25:boss?r.level+4:(region===0?(Math.abs(s.x-8)+Math.abs(s.y-8)<=6?1:3):r.level)+Math.floor(rng(s)*2),rare=!boss&&rng(s)<.025,aptitudes=opening?{vitality:1,force:1}:rare?{vitality:3,force:3}:{vitality:Math.floor(rng(s)*4),force:Math.floor(rng(s)*4)};const enemy=createMonster(id,level,rare,aptitudes,opening?3:null);if(!s.seen.includes(id))s.seen.push(id);const roster=final?[createMonster(15,24),enemy]:boss?[enemy]:[];const first=final?createMonster(12,23):boss?createMonster([0,2,3,11][region],r.level+2):enemy;return {enemy:first,roster,totalEnemies:boss?(final?3:2):1,region,boss,final,turn:0,active:Math.max(0,active(s)),log:[final?'灯台の守護竜 ルミドラが姿を現した！':boss?`${r.bossName}が勝負を挑んできた！`:`野生の${SPECIES[id].name}${enemy.rare?'（星色）':''}が現れた！`],result:null,guard:false};}
const MASTER_TEAMS=[[4,40,13],[6,42,27],[5,41,36],[15,47,14]];
export function masterEncounter(s,region){migratePostgame(s);if(!s.ended||!Number.isInteger(region)||region<0||region>3||s.postgame.tower||s.postgame.rift)return null;heal(s);const rank=s.postgame.guardianRanks[region]+1,base=Math.min(38,24+region*2+Math.floor((rank-1)*1.5)),foes=MASTER_TEAMS[region].map((id,i)=>createMonster(id,Math.min(40,base+i),rank>=5&&i===2,{vitality:Math.min(3,1+Math.floor(rank/3)),force:Math.min(3,1+Math.floor((rank+1)/3))},(region+i+rank)%NATURES.length));return {enemy:foes[0],roster:foes.slice(1),totalEnemies:3,region,boss:true,final:false,master:true,masterRank:rank,turn:0,active:Math.max(0,active(s)),log:[`${REGIONS[region].bossName}の強化戦・第${rank}段階。3体の精鋭が立ちはだかる！`],result:null,guard:false};}
function towerFoe(floor,slot){return createMonster((floor*5+slot*7)%16,Math.min(40,17+floor+Math.floor(slot/2)));}
export function towerEncounter(s){const run=s.postgame?.tower;if(!s.ended||!run||run.waiting)return null;const count=run.floor%5===0?3:2,foes=Array.from({length:count},(_,i)=>towerFoe(run.floor,i));return {enemy:foes[0],roster:foes.slice(1),totalEnemies:count,region:run.floor%4,boss:true,final:false,tower:true,towerFloor:run.floor,turn:0,active:Math.max(0,active(s)),log:[`星巡りの塔 ${run.floor}階。${count}体の試練が始まる！`],result:null,guard:false};}
export function startTower(s){migratePostgame(s);if(!s.ended||s.postgame.tower||s.postgame.rift)return null;heal(s);s.postgame.tower={floor:1,pending:0,waiting:false};return towerEncounter(s);}
export function continueTower(s,choice='next'){migratePostgame(s);const run=s.postgame.tower;if(!s.ended||!run||!run.waiting)return null;const checkpoint=run.floor%5===0;if(checkpoint&&!['heal','bonus'].includes(choice)||!checkpoint&&choice!=='next')return null;if(choice==='heal')heal(s);if(choice==='bonus')run.pending+=5;run.floor++;run.waiting=false;return towerEncounter(s);}
export function retireTower(s){migratePostgame(s);const run=s.postgame.tower;if(!run?.waiting)return false;s.postgame.medals+=run.pending;s.postgame.runs++;s.postgame.tower=null;return true;}
export function buyResearch(s,item){migratePostgame(s);const offers={potion:{cost:6,key:'potions',amount:3},ball:{cost:8,key:'balls',amount:5}},offer=offers[item];if(!offer||s.postgame.medals<offer.cost)return false;s.postgame.medals-=offer.cost;s[offer.key]+=offer.amount;return true;}
export function researchTraining(s,index=0){migratePostgame(s);migrateAptitudes(s);const m=s.party[index];if(!m||s.postgame.medals<10||m.aptitudes.vitality>=3&&m.aptitudes.force>=3)return false;s.postgame.medals-=10;const oldMax=maxHP(m);if(m.aptitudes.vitality<=m.aptitudes.force)m.aptitudes.vitality++;else m.aptitudes.force++;m.hp=Math.min(maxHP(m),m.hp+maxHP(m)-oldMax);return true;}
export function researchNature(s,index=0){migratePostgame(s);migrateAptitudes(s);const m=s.party[index];if(!m||s.postgame.medals<6)return false;s.postgame.medals-=6;m.nature=(m.nature+1)%NATURES.length;return true;}
function riftHash(run,salt=0){let x=(run.seed+Math.imul(run.floor+salt,2654435761))>>>0;x^=x>>>16;x=Math.imul(x,2246822507)>>>0;return (x^(x>>>13))>>>0;}
export const RIFT_SPECIES=[50,51,52,53,54,55];
const RIFT_DEPTHS=[3,5,7,9,11,13];
function riftFoeId(run,slot,final){const eligible=RIFT_SPECIES.filter((_,i)=>run.floor>=RIFT_DEPTHS[i]),last=final?2:1;if(eligible.length&&slot===last&&(final||riftHash(run,slot+19)%4===0))return eligible[riftHash(run,slot+31)%eligible.length];return (riftHash(run,slot+1)+slot*3)%50;}
export function riftRoom(s){const run=s.postgame?.rift;if(!s.ended||!run||!run.waiting)return null;if(run.complete)return {kind:'exit',name:'帰還の門',text:'裂け目の最深部を踏破した。報酬を確定して帰還できる。'};const roll=riftHash(run),kinds=['battle','treasure','shrine','hazard'],kind=run.floor===1||run.floor===run.maxFloor?'battle':kinds[roll%kinds.length],modifiers=['濃霧：相手の属性が読みにくい','活性：敵のレベルが2上がる','静穏：勝利報酬が1枚増える'];return {kind,name:{battle:'揺らぐ獣道',treasure:'星屑の宝箱',shrine:'月映りの泉',hazard:'崩れる近道'}[kind],text:kind==='battle'?modifiers[(roll>>>3)%modifiers.length]:kind==='treasure'?'クリスタルか研究記録が眠っている。':kind==='shrine'?'仲間を癒すか、泉を調べて研究記録を得られる。':'安全に調査するか、傷を負う危険を承知で近道を進める。',modifier:kind==='battle'?(roll>>>3)%3:null};}
export function startRift(s){migratePostgame(s);if(!s.ended||s.postgame.rift||s.postgame.tower)return null;heal(s);const seed=Math.floor(rng(s)*0xffffffff)>>>0;s.postgame.rift={seed,floor:1,maxFloor:5+seed%11,pending:0,waiting:true,complete:false};return riftRoom(s);}
function finishRiftFloor(s,reward){const run=s.postgame.rift;run.pending+=reward;s.postgame.riftBest=Math.max(s.postgame.riftBest,run.floor);if(run.floor>=run.maxFloor)run.complete=true;else run.floor++;run.waiting=true;if(run.walk)resetRiftWalk(run);}
export function riftEncounter(s){const run=s.postgame?.rift,room=riftRoom(s);if(!run||room?.kind!=='battle'||run.complete)return null;const final=run.floor===run.maxFloor,count=final?3:2,bonus=room.modifier===1?2:0,foes=Array.from({length:count},(_,i)=>createMonster(riftFoeId(run,i,final),Math.min(40,15+run.floor+bonus+Math.floor(i/2)),riftHash(run,i+7)%50===0));run.waiting=false;for(const foe of foes)if(!s.seen.includes(foe.id))s.seen.push(foe.id);return {enemy:foes[0],roster:foes.slice(1),totalEnemies:count,region:run.floor%4,boss:true,final:false,rift:true,riftFloor:run.floor,riftModifier:room.modifier,turn:0,active:Math.max(0,active(s)),log:[`夢の裂け目 ${run.floor}/${run.maxFloor}層。「${room.name}」の試練！`],result:null,guard:false};}
export function resolveRift(s,choice){const run=s.postgame?.rift,room=riftRoom(s);if(!run||run.complete||!room||room.kind==='battle')return false;if(room.kind==='treasure'&&choice==='crystal'){s.balls+=2;finishRiftFloor(s,1);return true;}if(room.kind==='treasure'&&choice==='record'){finishRiftFloor(s,3);return true;}if(room.kind==='shrine'&&choice==='heal'){heal(s);finishRiftFloor(s,1);return true;}if(room.kind==='shrine'&&choice==='study'){finishRiftFloor(s,3);return true;}if(room.kind==='hazard'&&choice==='scout'){finishRiftFloor(s,1);return true;}if(room.kind==='hazard'&&choice==='rush'){for(const m of s.party)if(m.hp>0)m.hp=Math.max(1,m.hp-Math.max(1,Math.round(maxHP(m)*.12)));finishRiftFloor(s,4);return true;}return false;}
export function retireRift(s){migratePostgame(s);const run=s.postgame.rift;if(!run?.waiting)return false;s.postgame.medals+=run.pending+(run.complete?5:0);s.postgame.riftRuns++;s.postgame.rift=null;return true;}
function damage(s,a,b,heavy=false){return Math.max(1,Math.round(power(a)*(heavy?1.6:1)*effectiveness(SPECIES[a.id].type,SPECIES[b.id].type)*(.85+rng(s)*.3)));}
function finish(s,b,result){b.result=result;if(b.rift){const run=s.postgame.rift;if(result==='win'){s.wins++;const reward=2+Math.floor(b.riftFloor/4)+(b.riftModifier===2?1:0);for(const m of s.party)b.log.push(...addXP(m,Math.round(b.enemy.level*4*(m.hp>0?1:.5))));finishRiftFloor(s,reward);b.log.push(`探索を突破！ 研究メダル候補 +${reward}。`);if(run.complete)b.log.push('最深部に帰還の門が現れた！');}else if(result==='lose'){const lost=run?.pending||0;s.postgame.rift=null;heal(s);b.log.push(`裂け目から救出された。未確定の研究メダル ${lost}枚を失った。`);}return;}if(b.tower){const run=s.postgame.tower;if(result==='win'){const reward=2+Math.floor(b.towerFloor/5);s.wins++;run.pending+=reward;run.waiting=true;s.postgame.bestFloor=Math.max(s.postgame.bestFloor,b.towerFloor);for(const m of s.party)b.log.push(...addXP(m,Math.round(b.enemy.level*4*(m.hp>0?1:.5))));b.log.push(`塔の試練を突破！ 研究メダル候補 +${reward}（撤退時に確定）。`);}else if(result==='lose'){const lost=run?.pending||0;s.postgame.tower=null;heal(s);b.log.push(`塔から帰還した。未確定の研究メダル ${lost}枚を失った。`);}return;}if(result==='win'){const earned=b.boss?180:28+b.enemy.level*4;s.coins+=earned;s.wins++;b.log.push(`勝利！ ${earned}コインを手に入れた。`);for(const m of s.party)b.log.push(...addXP(m,Math.round(b.enemy.level*(b.boss?8:4)*(m.hp>0?1:.5))));for(const m of s.party){if(!s.caught.includes(m.id))s.caught.push(m.id);if(!s.seen.includes(m.id))s.seen.push(m.id);}if(b.boss&&!b.final&&!s.badges.includes(b.region)){s.badges.push(b.region);s.balls+=8;s.potions+=3;b.log.push('紋章を手に入れた！ 次のエリアへ進める。');}if(b.final){s.ended=true;b.log.push('四つの紋章が輝き、ルミナ島の灯台に光が戻った！');}}else if(result==='lose'){s.coins=Math.max(0,s.coins-40);heal(s);s.x=8;s.y=8;s.region=0;b.log.push('仲間が全員倒れた……里の診療所で回復した。');}}

function effects(b){return b.effects??(b.effects={ally:{},enemy:{}});}
function natureDamage(a,target){return (a.nature===0?1.08:1)*(target.nature===1?.92:1);}
function energyGain(m){return m.nature===2?2:1;}
function scaledDamage(s,b,a,target,multiplier,type,side){const e=effects(b)[side],masterPressure=side==='enemy'&&b.master?1+Math.min(.8,(b.masterRank-1)*.04):1;return Math.max(1,Math.round(damage(s,a,target,false)*multiplier*(effectiveness(type,SPECIES[target.id].type)/effectiveness(SPECIES[a.id].type,SPECIES[target.id].type))*(e.focus?1.35:1)*(e.weaken?.75:1)*natureDamage(a,target)*masterPressure));}
function executeMove(s,b,a,target,v,side){const own=effects(b)[side],other=effects(b)[side==='ally'?'enemy':'ally'];a.energy=v.cost?a.energy-v.cost:Math.min(4,a.energy+energyGain(a));b.log.push(`${SPECIES[a.id].name}の「${v.name}」！`);
 if(v.kind==='heal'){const n=Math.min(maxHP(a)-a.hp,Math.round(maxHP(a)*.28*(a.nature===3?1.15:1)));a.hp+=n;b.log.push(`HPが${n}回復した。`);return;}
 if(v.kind==='focus'){own.focus=4;b.log.push('集中した！ 次の3ターンの攻撃が強くなる。');return;}
 if(v.kind==='shield'){own.shield=1;b.log.push('結界でこのターンのダメージを減らす。');return;}
 let d=scaledDamage(s,b,a,target,v.power,v.type,side);if(other.shield)d=Math.max(1,Math.round(d*.4));if(side==='enemy'&&b.guard)d=Math.max(1,Math.round(d*.4));d=Math.min(target.hp,d);target.hp-=d;b.log.push(`${d}ダメージ${effectiveness(v.type,SPECIES[target.id].type)>1?'・効果抜群！':''}。`);
 if(v.kind==='drain'){const n=Math.min(maxHP(a)-a.hp,Math.ceil(d*.5));a.hp+=n;b.log.push(`HPを${n}吸収した。`);}
 if(v.kind==='weaken'&&target.hp>0){other.weaken=3;b.log.push('相手の威力が下がった。');}
 if(v.kind==='poison'&&target.hp>0){other.poison=3;b.log.push('相手に継続ダメージの印を残した。');}
}
function finishMaster(s,b,result){b.result=result;if(result==='win'){const reward=3+Math.min(7,b.masterRank);s.wins++;s.postgame.guardianWins++;s.postgame.guardianRanks[b.region]=Math.max(s.postgame.guardianRanks[b.region],b.masterRank);s.postgame.medals+=reward;for(const m of s.party)b.log.push(...addXP(m,Math.round(b.enemy.level*5*(m.hp>0?1:.5))));b.log.push(`強化番人に勝利！ 第${b.masterRank}段階を記録し、研究メダル ${reward}枚を確定した。`);}else{heal(s);b.log.push('強化戦の記録は更新されなかった。仲間を整えて再挑戦できる。');}}
function defeatedEnemy(s,b){if(b.enemy.hp>0)return false;if(b.roster?.length){b.log.push(`${SPECIES[b.enemy.id].name}を倒した！`);b.enemy=b.roster.shift();effects(b).enemy={};if(!s.seen.includes(b.enemy.id))s.seen.push(b.enemy.id);b.log.push(`次の相手、${SPECIES[b.enemy.id].name}が戦場へ！`);}else if(b.master)finishMaster(s,b,'win');else finish(s,b,'win');return true;}
function tickEffects(s,b,m){const e=effects(b);for(const [side,mon] of [['ally',m],['enemy',b.enemy]]){if(e[side].poison&&mon.hp>0){const d=Math.min(mon.hp,Math.max(1,Math.round(maxHP(mon)*.06)));mon.hp-=d;b.log.push(`${SPECIES[mon.id].name}は印で${d}ダメージ。`);}for(const key of ['poison','weaken','focus','shield'])if(e[side][key])e[side][key]--;}}
function settleTurn(s,b,m){tickEffects(s,b,m);b.guard=false;b.turn++;if(m.hp===0){b.log.push(`${SPECIES[m.id].name}は倒れた。`);const next=active(s);if(next<0){if(b.master)finishMaster(s,b,'lose');else finish(s,b,'lose');return;}b.active=next;effects(b).ally={};b.log.push(`${SPECIES[s.party[next].id].name}が戦場へ！`);}defeatedEnemy(s,b);}
export function act(s,b,action,index){
 if(b.result)return [];if(b.log.length>450)b.log.splice(0,b.log.length-450);const before=b.log.length;let m=s.party[b.active];
 if(action==='switch'){if(!s.party[index]||s.party[index].hp<=0||index===b.active)return [];b.active=index;m=s.party[index];effects(b).ally={};b.log.push(`${SPECIES[m.id].name}に交代！`);}
 else if(action==='potion'){if(s.potions<1){b.log.push('回復薬がない。');return b.log.slice(before);}if(m.hp===maxHP(m)){b.log.push('HPは満タンだ。');return b.log.slice(before);}s.potions--;m.hp=Math.min(maxHP(m),m.hp+50);b.log.push('回復薬でHPを50回復！');}
 else if(action==='capture'){if(b.boss&&!b.rift){b.log.push('番人の仲間は捕獲できない。');return b.log.slice(before);}if(b.rift&&(b.enemy.id<50||b.roster?.length)){b.log.push('裂け目限定種は編成の最後に現れた時だけ捕獲できる。');return b.log.slice(before);}if(!s.balls){b.log.push('捕獲クリスタルがない。');return b.log.slice(before);}s.balls--;const chance=.2+.68*(1-b.enemy.hp/maxHP(b.enemy));if(rng(s)<chance){const c={...b.enemy,moves:equippedMoves(b.enemy).map(v=>v.id),hp:maxHP(b.enemy),energy:4};(s.party.length<6?s.party:s.box).push(c);s.captures++;if(!s.caught.includes(c.id))s.caught.push(c.id);b.log.push(`${SPECIES[c.id].name}が仲間になった！${s.party.length===6?' 手持ち・ボックスを確認しよう。':''}`);b.result='capture';if(b.rift){finishRiftFloor(s,1);b.log.push('限定種の調査を終え、次の層へ進める。');}return b.log.slice(before);}b.log.push('クリスタルから飛び出した！');}
 else if(action==='run'){if(b.boss){b.log.push('この勝負からは逃げられない。');return b.log.slice(before);}if(rng(s)<.85){b.result='run';b.log.push('無事に逃げ切った。');return b.log.slice(before);}b.log.push('逃げられなかった！');}
 else if(action==='guard'){b.guard=true;m.energy=Math.min(4,m.energy+2);b.log.push('身を守って気力を2回復。');}
 else if(action==='move'){const v=equippedMoves(m).find(v=>v.id===index);if(!v)return [];if(m.energy<v.cost){b.log.push('気力が足りない。「守る」で回復しよう。');return b.log.slice(before);}if(v.kind==='heal'&&m.hp===maxHP(m)){b.log.push('HPは満タンだ。');return b.log.slice(before);}executeMove(s,b,m,b.enemy,v,'ally');if(b.enemy.hp===0){settleTurn(s,b,m);return b.log.slice(before);}}
 else if(action==='attack'||action==='skill'){if(action==='skill'&&m.energy<2){b.log.push('気力が足りない。「守る」で回復しよう。');return b.log.slice(before);}const heavy=action==='skill';m.energy=heavy?m.energy-2:Math.min(4,m.energy+energyGain(m));let d=scaledDamage(s,b,m,b.enemy,heavy?1.6:1,SPECIES[m.id].type,'ally');if(effects(b).enemy.shield)d=Math.max(1,Math.round(d*.4));b.enemy.hp=Math.max(0,b.enemy.hp-d);const eff=effectiveness(SPECIES[m.id].type,SPECIES[b.enemy.id].type);b.log.push(`${SPECIES[m.id].name}の${heavy?TYPES[SPECIES[m.id].type]+'の奥義':'攻撃'}！ ${d}ダメージ${eff>1?'・効果抜群！':eff<1?'・相性が悪い…':''}`);if(b.enemy.hp===0){settleTurn(s,b,m);return b.log.slice(before);}}
 else return [];
 const heavy=b.turn%3===2,enemy=b.enemy,choices=equippedMoves(enemy).filter(v=>v.cost<=enemy.energy);
 const healing=choices.find(v=>v.kind==='heal'&&enemy.hp<maxHP(enemy)*.3);
 const damaging=choices.filter(v=>v.power>0&&v.cost>0);
 const chosen=healing||(heavy&&damaging.length?damaging[Math.floor(b.turn/3)%damaging.length]:null);
 if(chosen)executeMove(s,b,enemy,m,chosen,'enemy');
 else {enemy.energy=Math.min(4,enemy.energy+energyGain(enemy));let d=scaledDamage(s,b,enemy,m,heavy?1.6:1,SPECIES[enemy.id].type,'enemy');if(b.guard||effects(b).ally.shield)d=Math.max(1,Math.round(d*.4));m.hp=Math.max(0,m.hp-d);b.log.push(`${SPECIES[enemy.id].name}の${heavy?'奥義':'攻撃'}！ ${d}ダメージ。`);}
 settleTurn(s,b,m);return b.log.slice(before);
}
function validPostgame(p){if(p===undefined)return true;if(!p||!Number.isInteger(p.medals)||p.medals<0||p.medals>1e10||!Number.isInteger(p.bestFloor)||p.bestFloor<0||p.bestFloor>999||!Number.isInteger(p.runs)||p.runs<0||p.runs>1e10)return false;if(p.guardianRanks!==undefined&&(!Array.isArray(p.guardianRanks)||p.guardianRanks.length!==4||p.guardianRanks.some(x=>!Number.isInteger(x)||x<0||x>1e6))||p.guardianWins!==undefined&&(!Number.isInteger(p.guardianWins)||p.guardianWins<0||p.guardianWins>1e10))return false;const t=p.tower;if(!(t===null||!!t&&Number.isInteger(t.floor)&&t.floor>=1&&t.floor<=999&&Number.isInteger(t.pending)&&t.pending>=0&&t.pending<=1e10&&typeof t.waiting==='boolean'))return false;if(p.riftBest!==undefined&&(!Number.isInteger(p.riftBest)||p.riftBest<0||p.riftBest>15)||p.riftRuns!==undefined&&(!Number.isInteger(p.riftRuns)||p.riftRuns<0||p.riftRuns>1e10))return false;const r=p.rift;if(r===undefined||r===null)return true;return !!r&&Number.isInteger(r.seed)&&r.seed>=0&&r.seed<=0xffffffff&&Number.isInteger(r.floor)&&r.floor>=1&&r.floor<=15&&Number.isInteger(r.maxFloor)&&r.maxFloor>=5&&r.maxFloor<=15&&r.floor<=r.maxFloor&&Number.isInteger(r.pending)&&r.pending>=0&&r.pending<=1e10&&typeof r.waiting==='boolean'&&typeof r.complete==='boolean'&&(!r.complete||r.floor===r.maxFloor)&&validRiftWalk(r);}
export function validState(v){if(!v||!validResearch(v)||!validCampaign(v.campaign)||!Number.isInteger(v.quest)||v.quest<0||v.quest>3||typeof v.ended!=='boolean'||v.version!==1||!Array.isArray(v.party)||!v.party.length||v.party.length>6||!Array.isArray(v.box)||v.box.length>500||!validPostgame(v.postgame))return false;for(const key of ['x','y','steps','region','coins','balls','potions','wins','captures','seed','playSeconds'])if(!Number.isFinite(v[key])||v[key]<0||v[key]>1e10)return false;if(v.x>=48||v.y>=36||v.region>3||!Array.isArray(v.badges)||v.badges.some(x=>!Number.isInteger(x)||x<0||x>3)||new Set(v.badges).size!==v.badges.length)return false;for(const key of ['caught','seen'])if(!Array.isArray(v[key])||v[key].some(x=>!Number.isInteger(x)||!SPECIES[x]))return false;return [...v.party,...v.box].every(m=>Number.isInteger(m.id)&&SPECIES[m.id]&&Number.isInteger(m.level)&&m.level>=1&&m.level<=40&&Number.isFinite(m.hp)&&m.hp>=0&&m.hp<=maxHP(m)&&Number.isFinite(m.xp)&&m.xp>=0&&Number.isFinite(m.energy)&&m.energy>=0&&m.energy<=4&&(m.nature===undefined||Number.isInteger(m.nature)&&m.nature>=0&&m.nature<NATURES.length)&&(m.aptitudes===undefined||!!m.aptitudes&&!Array.isArray(m.aptitudes)&&Object.keys(m.aptitudes).length===2&&['vitality','force'].every(k=>Number.isInteger(m.aptitudes[k])&&m.aptitudes[k]>=0&&m.aptitudes[k]<=3))&&(m.moves===undefined||(Array.isArray(m.moves)&&m.moves.length>=1&&m.moves.length<=4&&new Set(m.moves).size===m.moves.length&&m.moves.every(id=>Number.isInteger(id)&&MOVES[id]?.type===SPECIES[m.id].type&&MOVES[id].level<=m.level))));}
export function validBattle(b,s){if(b===null)return (!s?.postgame?.tower||s.postgame.tower.waiting)&&(!s?.postgame?.rift||s.postgame.rift.waiting);if(b?.effects!==undefined){if(!b.effects||Object.keys(b.effects).some(k=>!['ally','enemy'].includes(k)))return false;for(const side of ['ally','enemy']){const e=b.effects[side];if(!e||Array.isArray(e)||Object.entries(e).some(([k,v])=>!['poison','weaken','focus','shield'].includes(k)||!Number.isInteger(v)||v<0||v>4))return false;}}if(!b||!validState(s)||!Number.isInteger(b.region)||b.region<0||b.region>3||!Number.isInteger(b.active)||!s.party[b.active]||!Number.isInteger(b.turn)||b.turn<0||b.turn>10000||typeof b.boss!=='boolean'||typeof b.final!=='boolean'||typeof b.guard!=='boolean'||!Array.isArray(b.log)||b.log.length>500||b.log.some(x=>typeof x!=='string'||x.length>500)||![null,'win','lose','capture','run'].includes(b.result))return false;if(b.final&&!b.boss)return false;if(b.tower!==undefined&&b.tower!==true||b.rift!==undefined&&b.rift!==true||b.tower&&b.rift)return false;if(b.rift){const run=s.postgame?.rift;if(!b.boss||b.final||!Number.isInteger(b.riftFloor)||b.riftFloor<1||b.riftFloor>15||!Number.isInteger(b.riftModifier)||b.riftModifier<0||b.riftModifier>2||![null,'win','lose','capture'].includes(b.result))return false;const wonAtNext=run&&run.waiting&&(run.floor===b.riftFloor+1||run.complete&&run.floor===b.riftFloor);if((b.result===null&&(!run||run.waiting||run.floor!==b.riftFloor))||(['win','capture'].includes(b.result)&&!wonAtNext)||(b.result==='lose'&&run!==null))return false;}else if(b.riftFloor!==undefined||b.riftModifier!==undefined)return false;if(b.tower){const run=s.postgame?.tower;if(!b.boss||b.final||!Number.isInteger(b.towerFloor)||b.towerFloor<1||b.towerFloor>999||![null,'win','lose'].includes(b.result))return false;if((b.result===null&&(!run||run.waiting||run.floor!==b.towerFloor))||(b.result==='win'&&(!run||!run.waiting||run.floor!==b.towerFloor))||(b.result==='lose'&&run!==null))return false;}else if(b.towerFloor!==undefined)return false;const monsters=[b.enemy,...(Array.isArray(b.roster)?b.roster:[])];if(!b.enemy||monsters.length>3||monsters.some(m=>!validState({...s,party:[m],box:[]})))return false;if(b.roster!==undefined&&!Array.isArray(b.roster))return false;if(!Number.isInteger(b.totalEnemies)||b.totalEnemies<1||b.totalEnemies>3||monsters.length>b.totalEnemies)return false;return b.boss?b.totalEnemies>1:b.totalEnemies===1&&!b.roster?.length;}
export function tile(x,y){if(x<0||x>=48||y<0||y>=36)return 'wall';if(x===0||y===0||x===47||y===35)return 'tree';if(x===23||x===24||y===17||y===18||(y===8&&x>=11&&x<=23)||(y===12&&x>=24&&x<=39)||(y===28&&x>=12&&x<=39))return 'path';if((x>=5&&x<=11&&y>=5&&y<=11)||(x>=35&&x<=41&&y>=5&&y<=11)||(x>=5&&x<=11&&y>=25&&y<=31)||(x>=35&&x<=41&&y>=25&&y<=31))return 'town';if((x+y*3)%23===0)return 'tree';if((x*7+y*11)%29===0)return 'water';return (x+y)%4===0||((x*3+y)%5===0)?'grass':'ground';}
export function regionAt(x,y){return (x>=24?1:0)+(y>=18?2:0);}
export function canMove(s,x,y){const r=regionAt(x,y);if(r>s.badges.length)return 'gate';const t=tile(x,y);return ['wall','tree','water'].includes(t)?false:true;}
const validBattleCore=validBattle;
validBattle=function(b,s){if(b?.master!==undefined&&b.master!==true||b?.masterRank!==undefined&&!b.master)return false;if(b?.master){if(!s?.ended||!b.boss||b.final||b.tower||b.rift||!Number.isInteger(b.masterRank)||b.masterRank<1||b.masterRank>1e6||!Array.isArray(s.postgame?.guardianRanks))return false;const current=s.postgame.guardianRanks[b.region];if(b.result==='win'?current!==b.masterRank:current+1!==b.masterRank)return false;}return validBattleCore(b,s);};
